(function(){'use strict';if(window.__abTestingInit)return;window.__abTestingInit = true;var TRACK_URL =(typeof BASE_URL !== 'undefined' ? BASE_URL:'')+ '/api/ab/track';var fired ={};function send(experiment,variant,eventType,metadata){if(!experiment || !variant)return;var key = experiment + '|' + variant;if(fired[key])return;fired[key] = true;try{var body = JSON.stringify({experiment_name:experiment,variant:variant,event_type:eventType || 'click',metadata:metadata ||{}});if(navigator.sendBeacon){var blob = new Blob([body],{type:'application/json'});navigator.sendBeacon(TRACK_URL,blob);return;}fetch(TRACK_URL,{method:'POST',headers:{'Content-Type':'application/json'},body:body,keepalive:true}).catch(function(){});}catch(e){}}function attach(el){var exp = el.getAttribute('data-experiment');var var_ = el.getAttribute('data-variant');if(!exp)return;el.addEventListener('click',function(){send(exp,var_,'click',{href:el.getAttribute('href')|| null});},{passive:true});}function init(){var nodes = document.querySelectorAll('[data-experiment]');for(var i = 0;i < nodes.length;i++)attach(nodes[i]);}if(document.readyState === 'loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}window.ABTest ={track:send};})();